package com.jsirgalaxybase.terminal.client.ui2;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;

import com.jsirgalaxybase.terminal.TerminalActionType;
import com.jsirgalaxybase.terminal.TerminalMarketAccountCenterRow;
import com.jsirgalaxybase.terminal.client.component.TerminalMarketSectionState;
import com.jsirgalaxybase.terminal.client.viewmodel.TerminalHomeScreenModel;
import com.jsirgalaxybase.terminal.client.viewmodel.TerminalMarketSectionModel;
import com.jsirgalaxybase.ui2.component.ComponentUiDocument;
import com.jsirgalaxybase.ui2.component.StandardWidgets;
import com.jsirgalaxybase.ui2.component.UiActionHandler;
import com.jsirgalaxybase.ui2.core.UiContext;
import com.jsirgalaxybase.ui2.core.UiElement;
import com.jsirgalaxybase.ui2.core.UiNode;
import com.jsirgalaxybase.ui2.geometry.Insets;
import com.jsirgalaxybase.ui2.geometry.UiRect;
import com.jsirgalaxybase.ui2.geometry.UiSize;
import com.jsirgalaxybase.ui2.input.InputResult;
import com.jsirgalaxybase.ui2.input.UiEvent;
import com.jsirgalaxybase.ui2.input.UiInputHandler;
import com.jsirgalaxybase.ui2.input.UiInputNode;
import com.jsirgalaxybase.ui2.input.UiKeyCode;
import com.jsirgalaxybase.ui2.layout.LayoutKind;
import com.jsirgalaxybase.ui2.layout.LayoutSpec;

/** Modern order, fill, delivery and recovery center backed by structured server rows. */
public final class TerminalMarketAccountDocument extends ComponentUiDocument implements TerminalPageDocument {
    private final TerminalMarketSectionState state;private final TerminalAppShell.Actions shellActions;private final TerminalStandardMarketDocument.Actions actions;private final Runnable invalidation;
    private TerminalHomeScreenModel model;private boolean helpOpen;private Pending pending;private int width,height;
    public TerminalMarketAccountDocument(TerminalMarketSectionState state,TerminalHomeScreenModel model,TerminalAppShell.Actions shellActions,TerminalStandardMarketDocument.Actions actions,Runnable invalidation){super(StandardWidgets.create());this.state=state;this.model=model;this.shellActions=shellActions;this.actions=actions;this.invalidation=invalidation;state.applyModel(market());}
    @Override public void update(TerminalHomeScreenModel value){model=value;TerminalMarketSectionModel next=market();if(state.acceptsModel(next))state.applyModel(next);}
    @Override public void openHelp(){helpOpen=true;invalidation.run();}
    @Override public boolean refresh(){refreshHistory();return true;}
    @Override public UiElement build(UiContext context){final TerminalMarketSectionModel market=market();UiElement tabs=UiElement.type("Row").key("center-tabs").child(tab("center-open","当前委托",TerminalMarketSectionState.AccountCenterTab.OPEN_ORDERS)).child(tab("center-fills","成交记录",TerminalMarketSectionState.AccountCenterTab.FILLS)).child(tab("center-assets","资产与交付",TerminalMarketSectionState.AccountCenterTab.ASSETS_AND_DELIVERY)).child(tab("center-history","历史查询",TerminalMarketSectionState.AccountCenterTab.HISTORY)).build();UiElement summary=UiElement.type("Row").key("center-summary").child(metric("center-bank","银行可用",market.getCenterBankAvailable())).child(metric("center-frozen","冻结资金",market.getCenterFrozenFunds())).child(metric("center-vault","Base Vault",market.getCenterVaultUsedSlots()+" / "+market.getCenterVaultTotalSlots())).child(metric("center-orders","当前委托",String.valueOf(market.getCenterActiveOrders()))).child(metric("center-delivery","待收货",String.valueOf(market.getCenterPendingDeliveries()))).child(metric("center-recovery","恢复事项",String.valueOf(market.getCenterRecoveryItems()))).build();UiElement filters=UiElement.type("Row").key("center-filters").child(button("center-scope",state.getHistoryProductScopeLabel(),true,new Runnable(){public void run(){state.toggleHistoryProductScope();refreshHistory();}})).child(button("center-side",state.getHistorySideLabel(),true,new Runnable(){public void run(){state.cycleHistorySide();refreshHistory();}})).child(button("center-status",state.getHistoryStatusLabel(),true,new Runnable(){public void run(){state.cycleHistoryStatus();refreshHistory();}})).child(button("center-time",state.getHistoryTimeLabel(),true,new Runnable(){public void run(){state.cycleHistoryTime();refreshHistory();}})).child(button("center-clear","清除筛选",true,new Runnable(){public void run(){state.resetHistoryFilters();refreshHistory();}})).build();UiElement rows=rows(market);UiElement pager=UiElement.type("Row").key("center-pager").child(button("center-prev","‹",market.hasHistoryPreviousPage(),new Runnable(){public void run(){state.setHistoryPage(market.getHistoryPageIndex()-1);refreshHistory();}})).child(label("center-page",(market.getHistoryPageIndex()+1)+" / "+market.getHistoryTotalPages()+" · 共 "+market.getHistoryTotalEntries()+" 条","caption",false,"textMuted")).child(button("center-next","›",market.hasHistoryNextPage(),new Runnable(){public void run(){state.setHistoryPage(market.getHistoryPageIndex()+1);refreshHistory();}})).build();UiElement base=UiElement.type("Column").key("center-base").child(label("center-title","订单与资产中心","section",true,"text")).child(summary).child(tabs).child(filters).child(rows).child(pager).build();UiElement.Builder page=UiElement.type("Stack").key("center-root").child(base);if(pending!=null)page.child(UiElement.type("Dialog").key("center-confirm").prop(StandardWidgets.TEXT,pending.title).prop(StandardWidgets.DETAIL,pending.detail).prop(StandardWidgets.CANCEL_TEXT,"取消").prop(StandardWidgets.CONFIRM_TEXT,pending.confirm).build());if(helpOpen)page.child(UiElement.type("Dialog").key("center-help").prop(StandardWidgets.TEXT,"订单与交付帮助").prop(StandardWidgets.DETAIL,"这里聚合委托、成交、待交付和恢复事项。撤单与领取仍由服务端按订单版本和资产状态复核。").build());return TerminalAppShell.build(model,page.build(),shellActions,"订单与资产");}
    private UiElement rows(TerminalMarketSectionModel market){UiElement.Builder list=UiElement.type("Column").key("center-rows");List<TerminalMarketAccountCenterRow> rows=market.getAccountCenterRows();int count=Math.min(height<=220?4:6,rows.size());if(count==0)list.child(UiElement.type("EmptyState").key("center-empty").prop(StandardWidgets.TEXT,"当前筛选下没有记录").build());for(int i=0;i<count;i++){final TerminalMarketAccountCenterRow row=rows.get(i);UiElement.Builder card=UiElement.type("Card").key("center-row-"+i).child(UiElement.type("ExternalItem").key("center-row-icon-"+i).prop(StandardWidgets.EXTERNAL_ID,"center-item-"+i).build()).child(label("center-row-title-"+i,rowTitle(row),"caption",true,"text")).child(label("center-row-detail-"+i,rowDetail(row),"caption",false,"textMuted"));if(row.isCancelable())card.child(button("center-row-action-"+i,"撤单",true,new Runnable(){public void run(){state.prepareCancelOrder(row.getRecordId(),row.getUpdatedAtEpochSeconds());pending=new Pending(TerminalActionType.MARKET_CANCEL_ORDER,state.toHistoryPayload().encodeHistory(),"确认撤单","订单 "+row.getRecordId()+"；服务端将校验剩余量和版本。","确认撤单");invalidation.run();}}));else if("DELIVERY".equalsIgnoreCase(row.getKind())&&isPending(row.getStatus()))card.child(button("center-row-action-"+i,"领取",true,new Runnable(){public void run(){state.setPendingClaimCustodyId(row.getRecordId());pending=new Pending(TerminalActionType.MARKET_CLAIM_ASSET,state.toPayload().encode(),"领取资产","交付记录 "+row.getRecordId()+" 将尝试进入 Base Vault。","确认领取");invalidation.run();}}));list.child(card.build());}return list.build();}
    private UiElement tab(String key,String text,final TerminalMarketSectionState.AccountCenterTab tab){return UiElement.type("Tab").key(key).prop(StandardWidgets.TEXT,text).prop(StandardWidgets.SELECTED,state.getAccountCenterTab()==tab).prop(StandardWidgets.ACTION,handler(new Runnable(){public void run(){state.selectAccountCenterTab(tab);refreshHistory();}})).build();}
    private static UiElement metric(String key,String name,String value){return UiElement.type("Card").key(key).child(label(key+"-name",name,"caption",false,"textMuted")).child(label(key+"-value",value,"caption",true,"text")).build();}
    @Override public LayoutSpec layout(UiElement root,UiSize viewport,UiContext context){width=viewport.getWidth();height=viewport.getHeight();boolean compact=TerminalWindowMetrics.compute(viewport).getBounds().getHeight()<=220;LayoutSpec tabs=LayoutSpec.of("center-tabs",LayoutKind.ROW).preferred(0,compact?14:18).gap(2).child(flex("center-open")).child(flex("center-fills")).child(flex("center-assets")).child(flex("center-history")).build();LayoutSpec.Builder summary=LayoutSpec.of("center-summary",LayoutKind.ROW).preferred(0,compact?25:34).gap(2);String[] metrics={"center-bank","center-frozen","center-vault","center-orders","center-delivery","center-recovery"};for(String key:metrics)summary.child(LayoutSpec.of(key,LayoutKind.COLUMN).flex(1F).padding(new Insets(2,3,2,3)).child(LayoutSpec.of(key+"-name",LayoutKind.LEAF).preferred(0,9).build()).child(LayoutSpec.of(key+"-value",LayoutKind.LEAF).flex(1F).build()).build());LayoutSpec filters=LayoutSpec.of("center-filters",LayoutKind.ROW).preferred(0,compact?14:18).gap(2).child(flex("center-scope")).child(flex("center-side")).child(flex("center-status")).child(flex("center-time")).child(flex("center-clear")).build();LayoutSpec.Builder rows=LayoutSpec.of("center-rows",LayoutKind.COLUMN).flex(1F).gap(2);int count=Math.min(compact?4:6,market().getAccountCenterRows().size());if(count==0)rows.child(LayoutSpec.of("center-empty",LayoutKind.LEAF).flex(1F).build());for(int i=0;i<count;i++){TerminalMarketAccountCenterRow row=market().getAccountCenterRows().get(i);LayoutSpec.Builder card=LayoutSpec.of("center-row-"+i,LayoutKind.ROW).flex(1F).padding(new Insets(2,3,2,3)).gap(3).child(LayoutSpec.of("center-row-icon-"+i,LayoutKind.LEAF).preferred(16,16).build()).child(LayoutSpec.of("center-row-title-"+i,LayoutKind.LEAF).preferred(compact?78:125,0).build()).child(LayoutSpec.of("center-row-detail-"+i,LayoutKind.LEAF).flex(1F).build());if(row.isCancelable()||("DELIVERY".equalsIgnoreCase(row.getKind())&&isPending(row.getStatus())))card.child(LayoutSpec.of("center-row-action-"+i,LayoutKind.LEAF).preferred(42,0).build());rows.child(card.build());}LayoutSpec pager=LayoutSpec.of("center-pager",LayoutKind.ROW).preferred(0,compact?14:18).gap(2).child(LayoutSpec.of("center-prev",LayoutKind.LEAF).preferred(26,0).build()).child(LayoutSpec.of("center-page",LayoutKind.LEAF).flex(1F).build()).child(LayoutSpec.of("center-next",LayoutKind.LEAF).preferred(26,0).build()).build();LayoutSpec base=LayoutSpec.of("center-base",LayoutKind.COLUMN).padding(new Insets(3,4,3,4)).gap(2).child(LayoutSpec.of("center-title",LayoutKind.LEAF).preferred(0,14).build()).child(summary.build()).child(tabs).child(filters).child(rows.build()).child(pager).build();LayoutSpec.Builder page=LayoutSpec.of("center-root",LayoutKind.STACK).flex(1F).child(base);if(pending!=null)page.child(LayoutSpec.of("center-confirm",LayoutKind.LEAF).build());if(helpOpen)page.child(LayoutSpec.of("center-help",LayoutKind.LEAF).build());return TerminalAppShell.layout(viewport,model,page.build());}

    @Override public Map<String,ItemStack> externalItems(){Map<String,ItemStack> result=new LinkedHashMap<String,ItemStack>();List<TerminalMarketAccountCenterRow> rows=market().getAccountCenterRows();int count=Math.min(height<=220?4:6,rows.size());for(int i=0;i<count;i++){TerminalMarketAccountCenterRow row=rows.get(i);Object item=Item.itemRegistry.getObject(row.getRegistryName());if(item instanceof Item)result.put("center-item-"+i,new ItemStack((Item)item,1,row.getMeta()));}return Collections.unmodifiableMap(result);}
    @Override public UiInputNode modalInput(UiNode root,UiContext context){final boolean confirm=pending!=null;if(!confirm&&!helpOpen)return null;return new UiInputNode(confirm?"center-confirm":"center-help",new UiRect(0,0,width,height),true,new UiInputHandler(){public InputResult handle(UiInputNode target,UiEvent event){if(event.getPhase()!=UiEvent.Phase.TARGET)return InputResult.PASS;if(confirm&&event.getType()==UiEvent.Type.KEY_DOWN&&event.getKeyCode()==UiKeyCode.ENTER){submit();return InputResult.CONSUMED;}if(confirm&&event.getType()==UiEvent.Type.POINTER_DOWN){if(confirmHit(event))submit();else{pending=null;invalidation.run();}return InputResult.CONSUMED;}if((event.getType()==UiEvent.Type.KEY_DOWN&&event.getKeyCode()==UiKeyCode.ESCAPE)||event.getType()==UiEvent.Type.POINTER_DOWN){pending=null;helpOpen=false;invalidation.run();return InputResult.CONSUMED;}return InputResult.PASS;}});}
    private void submit(){Pending value=pending;if(value!=null)actions.sendMarket(value.action,value.payload);pending=null;invalidation.run();}
    private boolean confirmHit(UiEvent event){int dw=Math.min(230,Math.max(80,width-40)),dh=Math.min(90,Math.max(50,height-30)),dx=(width-dw)/2,dy=(height-dh)/2,half=Math.max(0,(dw-28)/2);return new UiRect(dx+10+half+8,dy+dh-22,half,16).contains(event.getX(),event.getY());}
    private void refreshHistory(){actions.sendMarket(TerminalActionType.MARKET_REFRESH_HISTORY,state.toHistoryPayload().encodeHistory());}
    private TerminalMarketSectionModel market(){TerminalHomeScreenModel.PageSnapshotModel page=model.getPageSnapshot("market");return page.hasMarketSectionModel()?page.getMarketSectionModel():TerminalMarketSectionModel.placeholder("market_account_center");}
    private static String rowTitle(TerminalMarketAccountCenterRow row){String item=row.getRegistryName().isEmpty()?row.getMessage():localized(row);return row.getSide()+" · "+item;}
    private static String rowDetail(TerminalMarketAccountCenterRow row){return "价 "+row.getUnitPrice()+" · 成交 "+row.getFilledQuantity()+"/"+row.getOriginalQuantity()+" · 剩余 "+row.getRemainingQuantity()+" · "+row.getStatus()+" · "+row.getCreatedAt();}
    private static String localized(TerminalMarketAccountCenterRow row){Object item=Item.itemRegistry.getObject(row.getRegistryName());if(item instanceof Item){try{return new ItemStack((Item)item,1,row.getMeta()).getDisplayName();}catch(RuntimeException ignored){}}return row.getRegistryName()+":"+row.getMeta();}
    private static boolean isPending(String status){return status==null||status.isEmpty()||"PENDING".equalsIgnoreCase(status)||"READY".equalsIgnoreCase(status)||"FAILED".equalsIgnoreCase(status);}
    private static LayoutSpec flex(String key){return LayoutSpec.of(key,LayoutKind.LEAF).flex(1F).build();}
    private static UiElement button(String key,String text,boolean enabled,Runnable run){return UiElement.type("Button").key(key).prop(StandardWidgets.TEXT,text).prop(StandardWidgets.ENABLED,enabled).prop(StandardWidgets.ACTION,handler(run)).build();}
    private static UiActionHandler handler(final Runnable run){return new UiActionHandler(){public InputResult handle(UiEvent event){run.run();return InputResult.CONSUMED;}};}
    private static UiElement label(String key,String text,String role,boolean bold,String tone){return UiElement.type("Label").key(key).prop(StandardWidgets.TEXT,text).prop(StandardWidgets.TEXT_ROLE,role).prop(StandardWidgets.MAX_LINES,1).prop(StandardWidgets.BOLD,bold).prop(StandardWidgets.TONE,tone).build();}
    private static final class Pending{private final TerminalActionType action;private final String payload,title,detail,confirm;private Pending(TerminalActionType action,String payload,String title,String detail,String confirm){this.action=action;this.payload=payload;this.title=title;this.detail=detail;this.confirm=confirm;}}
}
